import React from "react";
import { useState, useEffect, useRef } from "react";
import { useForm } from "react-hook-form";
import { toast } from "react-toastify";
import Select from "react-select";
import Modal from "react-bootstrap/Modal";
import Button from "react-bootstrap/Button";
import { useSearchParams, useNavigate } from "react-router-dom";
import { generateUUID, compressBase64, decompressBase64 } from "../../components/utilities/utils";
import { GetGrpLedgerList } from "../dataservice/getGrpLedgerList";
import { GetCmbGrpLedgers } from "../dataservice/getCmbGrpLedgers";
import apiAcc from "../../components/api/AccWebcall";
import api from "../../components/api/Webcall";
import appsettings from "../../appsettings.json"
const apiendpoints = appsettings.ApiEndpoints;

function AccountGroup() {

    const navigate = useNavigate();
    const { register, getValues, setValue, reset } = useForm();
    const [searchParams, setSearchParams] = useSearchParams();

    let qDet = useRef(JSON.parse(decompressBase64(atob(searchParams.get("_q")))));

    let addoredit = useRef("Add");

    let norPP = useRef(10);
    const [norSkip, setNorSkip] = useState(0);

    const [ledgers, setLedgers] = useState(null);
    const [cmbparentgroupledger, setcmbparentgroupledger] = useState([]);
    const [cmbasegroupledger, setcmbbasegroupledger] = useState([]);
    const [lggroups, setLgGroups] = useState([]);
    const [currencyid, setCurrencyId] = useState(0);
   
    const [groupid, setgroupId] = useState(0);
    const [parentgrpid, setparentgrpid] = useState(0);
    const [basegrpid, setbasegrpid] = useState(0);

    const [isLedgerNameDisabled, setLedgerNameDisabled] = useState(false);
    const [isbasegroupdisabled, setbasegroupdisabled] = useState(false);
    const [issavedisabled, setsavedisabled] = useState(false);

    const [showModal, setShowModal] = useState(false);
    const modelHandleHide = () => setShowModal(false);


    const fetctLedgers = async (skip, nrp) => {
        let frmData = {};
        frmData["skip"] = skip;
        frmData["top"] = nrp;
        const res = await GetGrpLedgerList(frmData);   
        if (res) {
            if (res.hdr) {
                if (res.hdr.rst && res.hdr.rst !== "SUCCESS") {
                    if (res.fdr) {
                        setTimeout(() => {

                            let strMsg = "";
                            res.fdr.map((data) => { strMsg += data.rstmsg + ", " });

                            toast.error(strMsg);

                        }, 300);
                    }
                }
                else {
                    if (res.body) {

                        if (res.body.grpledgers) {
                            setLedgers(res.body.grpledgers);
                        }

                    }
                }
            }
        }

        const cmbres = await GetCmbGrpLedgers();
        if (cmbres)
        {           
           if (cmbres.grplgrcmb)
           {
                let parentgroupledger = cmbres.grplgrcmb;
                const parentledger = [];
                parentledger.push({ value: null, label: "- Select -"});
                parentgroupledger.map((data, i) => { parentledger.push({ value: data.grid, label: data.grna }) });    
                setcmbparentgroupledger(parentledger)
           }

           if (cmbres.bgcmb)
            {
                 let basegroupledger = cmbres.bgcmb;
                 const baseGroup  = [];
                 baseGroup.push({ value: null, label: "- Select -"});
                 basegroupledger.map((data, i) => { baseGroup.push({ value: data.bgrid, label: data.bgrna }) });    
                 setcmbbasegroupledger(baseGroup)
            }
        }

    }

    const onClick_FirstPage = () =>{
        let rPP = Number(getValues("cmbRowPP"));
        let no = 0;
        setNorSkip(no);
        fetctLedgers(norSkip, rPP);  
    }

    const onClick_LastPage = () =>{
        let rPP = Number(getValues("cmbRowPP"));
        let no = 0;
        setNorSkip(no);
        fetctLedgers(norSkip, rPP);  
    }

    const onClick_RightArrow = () =>{
        let rPP = Number(getValues("cmbRowPP"));
        let no = norSkip + rPP;
        setNorSkip(no);
        fetctLedgers(norSkip, rPP);
    }

    const onClick_LeftArrow = () =>{
        let rPP = Number(getValues("cmbRowPP"));
        let no = norSkip - rPP;
        if (no<=0){ no = 0;}
        setNorSkip(no);
        fetctLedgers(norSkip, rPP);
    }

    const onChange_cmbRowPP = (e) => {
        fetctLedgers(norSkip, e.target.value);
    }

    const onChange_cmbParentGroup = (obj) => {
        setparentgrpid(obj.value);

        let grp = ledgers.find(x => x.pgid == obj.value);

        if (obj.value!==null ) {
            
            setbasegrpid(grp.bgid);

            setbasegroupdisabled(true);
        }
        else{
            setbasegroupdisabled(false);
        }
    }

    const onChange_cmbbaseGroup = (obj) => {
        setbasegrpid(obj.value);
        setsavedisabled(false)
        setparentgrpid(null);
    }

    const addNewLedger = () => {
        reset({ txtLedgerId: 0, txtLedgerName: null });    
        setgroupId(null);
        setparentgrpid(null);
        setbasegrpid(null);
        setLedgerNameDisabled(false);
        setbasegroupdisabled(false);
        setShowModal(true);
    }
    

    const editLedger = (gid) => {
        let ledg = ledgers.find(x => x.gid == gid);
        reset({ txtLedgerId: gid, txtLedgerName: ledg.gna });       
        setgroupId(ledg.gid);
        setparentgrpid(ledg.pgid);
        setbasegrpid(ledg.bgid);
        setLedgerNameDisabled(true);
        if (ledg.pgid && ledg.pgid !== null)
        {
            setbasegroupdisabled(true);
        }
        else
        {
            setbasegroupdisabled(false);
        }
        setShowModal(true);
    }

    const saveLedger = (e) => {
       
        setsavedisabled(true);
         if (parentgrpid==null&&basegrpid==null)
         {
             let strMsg = "Base group is mandatory";          
             toast.error(strMsg);            
             return;
         }

        let frmData = {};

        frmData["txtGroupId"] = getValues("txtLedgerId");
        frmData["txtGroupName"] = getValues("txtLedgerName");
        frmData["cmbParentGroupId"] = parentgrpid;
        frmData["cmbBaseGroupId"] = basegrpid;

        const convID = generateUUID();
        const frmHdr = { convid: convID, tag: "Save Ledger", orgid: "", vendid: "_Acc" };
        const data = { hdr: frmHdr, body: frmData };
        const reqHdr = {};
        apiAcc.post(apiendpoints.Updgrouplgr, data, reqHdr)
            .then(function (response) {
                const res = response.data;
                if (res) {
                    if (res.hdr) {
                        if (res.hdr.rst && res.hdr.rst !== "SUCCESS") {

                            e.target.disabled = false;

                            if (res.fdr) {
                                setTimeout(() => {

                                    let strMsg = "";
                                    res.fdr.map((data) => { strMsg += data.rstmsg + ", " });

                                    toast.error(strMsg);

                                }, 300);
                            }
                        }
                        else {

                            fetctLedgers();
                            setShowModal(false);

                        }
                    }
                }
            });
    }


    /*  Use Effect */
    useEffect(() => {
        fetctLedgers(norSkip, norPP.current);
    }, []);


    return (

        <>

            <div className="row pad-top-0-5em pad-left-15 pad-right-15">

                <div className="card-header">

                    <strong className="card-title">Account Group</strong>

                    <div className=" float-end">
                        <button className="btn-link btn-bg"><i class="bi bi-chevron-bar-left" onClick={()=>{ onClick_FirstPage(); } }></i></button>
                        <button className="btn-link btn-bg"><i class="bi bi-caret-left" onClick={()=>{ onClick_LeftArrow(); }}></i></button>
                        <select {...register("cmbRowPP")} style={{ fontSize: "10pt" }} onChange={(e) => { onChange_cmbRowPP(e); }}>
                            <option value="10">10</option>
                            <option value="25">25</option>
                            <option value="50">50</option>
                            <option value="100">100</option>
                        </select>
                        <button className="btn-link btn-bg"><i class="bi bi-caret-right" onClick={()=>{ onClick_RightArrow(); }}></i></button>
                        <button className="btn-link btn-bg"><i class="bi bi-chevron-bar-right" onClick={()=>{ onClick_LastPage(); }}></i></button>
                        <button onClick={() => { addNewLedger(); }} className="btn-link">+ Add New</button>
                    </div>

                </div>

            </div>

            <div className="row pad-top-0-5em pad-left-15 pad-right-15">

                <table className="lst-grid">
                    <thead>
                        <tr>
                            <th>Id</th>
                            <th>Group Name</th>
                            <th>Parent Group </th>
                            <th>Base Group </th>                            
                            <th>Manage</th>                        
                        </tr>
                    </thead>
                    <tbody>

                        {(ledgers !== null) ?
                            ledgers.map((data, i) => {
                                return (
                                    <tr className="ledger-row">
                                        <td>{data["gid"]}</td>
                                        <td>{data["gna"]}</td>                                       
                                        <td>{data["pgna"]}</td>  
                                        <td>{ data["bgna"]}</td>     
                                        <td> <button type="button" className="btn-link" onClick={() => { editLedger(data["gid"]) }}>edit</button> </td>
                                    </tr>
                                )
                            })
                            : <tr> <td colSpan={7}> Loading... </td> </tr>
                        }

                    </tbody>
                </table>

            </div>


            <Modal show={showModal} onHide={modelHandleHide} size="xl"
                aria-labelledby="contained-modal-title-vcenter" centered >

                <Modal.Header>
                    <Modal.Title>{addoredit.current} Account Head</Modal.Title>
                    <div className="float-end">
                        <label>Id :&nbsp;</label>
                        <input type="text" {...register("txtLedgerId")} disabled="true" />
                    </div>
                </Modal.Header>

                <Modal.Body>

                    <div className="row">

                        <div className="row pad-bottom-0-5em">

                            <div className="col-md-8">
                                <label htmlFor="txtLedgerName" className="form-label">Group Name</label>
                                <input type="text" className="form-control" {...register("txtLedgerName")} disabled={isLedgerNameDisabled} />
                            </div>

                            <div className="col-md-4">
                                <label htmlFor="cmbParentGroupId" className="form-label">Parent Group </label>
                                <Select {...register("cmbParentGroupId")} options={cmbparentgroupledger} 
                                    value={cmbparentgroupledger.find(x => x.value === parentgrpid)}                                   
                                    onChange={(e) => { onChange_cmbParentGroup(e); }} > </Select>
                            </div>

                        </div>

                        <div className="row pad-bottom-0-5em">

                            <div className="col-md-8">
                                <label htmlFor="cmbBaseGroupId" className="form-label">Base Group</label>
                                <Select {...register("cmbBaseGroupId")} options={cmbasegroupledger} isDisabled={isbasegroupdisabled}
                                    value={cmbasegroupledger.find(x => x.value === basegrpid)}
                                    onChange={e => { onChange_cmbbaseGroup(e); }} > </Select>
                            </div>                          

                        </div>

                    </div>

                </Modal.Body>

                <Modal.Footer>
                    <Button variant="secondary" onClick={(e) => { saveLedger(e); e.target.disabled = issavedisabled; }}>Save</Button>
                    <Button variant="secondary" onClick={() => { setShowModal(false); }}>Cancel</Button>
                </Modal.Footer>

            </Modal>

        </>
    );
}

export default AccountGroup;
