import { generateUUID, compressBase64, decompressBase64 } from "../../components/utilities/utils";
import apiAcc from "../../components/api/AccWebcall";
import appsettings from "../../appsettings.json"

const apiendpoints = appsettings.ApiEndpoints;

export const GetCmbGrpLedgers = async () => {

    let Response;

    const convID = generateUUID();
    const frmHdr = { convid: convID, tag: "Ledgers for Combo", orgid: "", vendid: "_Acc" };
    const frmData = {};
    const data = { hdr: frmHdr, body: frmData };

    const reqHdr = {};

    await apiAcc.post(apiendpoints.GrpLedgerCmb, data, reqHdr)
        .then(function (response) {
            const strResponse = response.data;
            Response = strResponse.body;
        });

    return Response;

};
